// pattern (text left, image right on desktop), rewritten on the design system tokens.

import { useReducedMotion } from 'react';
import { m, LazyMotion, domAnimation } from 'framer-motion';

type Fact = { title: string; text?: string };
type Link = { label: string; href: string };

export type WhyNoPainProps = {
  title: string;
  items: Fact[];
  photo?: string;
  photoAlt?: string;
  cta?: Link;
};

export default function WhyNoPain({ title, items, photo, photoAlt, cta }: WhyNoPainProps) {
  const prefersReduced = useReducedMotion();
  const animate = prefersReduced ? false : 'calm';

  const factVariants = {
    hidden: { opacity: 0, y: 16 },
    visible: (i: number) => ({
      opacity: 1,
      y: 0,
      transition: { delay: i * 0.15, duration: 0.5, ease: 'easeOut' },
    }),
  };

  return (
    <LazyMotion features={domAnimation}>
      <section className="bg-background font-sans py-section">
        <div className="mx-auto flex w-full max-w-page flex-col gap-10 px-gutter md:flex-row md:items-center md:gap-16">
          {/* Text column */}
