// «Почему не больно»: two facts — equipment and anaesthesia — with a supporting photo.
// Shows anxious patients the clinic treats without pain. Composition after a split-feature
// pattern (text left, image right on desktop), rewritten on the design system tokens.

import { useReducedMotion } from 'react';
import { m, LazyMotion, domAnimation } from 'framer-motion';

type Fact = { title: string; text?: string };
type Link = { label: string; href: string };

export type WhyNoPainProps = {
  title: string;
  items: Fact[];
  photo?: string;
  photoAlt?: string;
  cta?: Link;
};

export default function WhyNoPain({ title, items, photo, photoAlt, cta }: WhyNoPainProps) {
  const prefersReduced = useReducedMotion();
  const animate = prefersReduced ? false : 'calm';

  const factVariants = {
    hidden: { opacity: 0, y: 16 },
    visible: (i: number) => ({
      opacity: 1,
      y: 0,
      transition: { delay: i * 0.15, duration: 0.5, ease: 'easeOut' },
    }),
  };

  return (
    <LazyMotion features={domAnimation}>
      <section className="bg-background font-sans py-section">
        <div className="mx-auto flex w-full max-w-page flex-col gap-10 px-gutter md:flex-row md:items-center md:gap-16">
          {/* Text column */}
          <div className="min-w-0 md:flex-1">
            <h2 className="font-display text-h2 font-bold text-foreground text-balance wrap-break-word">
              {title}
            </h2>

            <ul className="mt-8 flex flex-col gap-6" role="list">
              {items.map((item, i) => (
                <li key={i} className="flex gap-4">
                  {/* Accent bar */}
                  <span
                    className="mt-1 block h-10 w-1 shrink-0 rounded-full bg-primary"
                    aria-hidden="true"
                  />
                  <div className="min-w-0">
                    <h3 className="font-display text-h3 font-semibold text-foreground">
                      {item.title}
                    </h3>
                    {item.text ? (
                      <p className="mt-1 text-body text-muted-foreground">{item.text}</p>
                    ) : null}
                  </div>
                </li>
              ))}
            </ul>

            {cta ? (
              <a
                href={cta.href}
                className="mt-8 inline-flex min-h-11 min-w-11 items-center justify-center rounded-control bg-primary px-6 text-body font-bold text-primary-foreground transition-opacity duration-200 hover:opacity-90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
              >
                {cta.label}
              </a>
            ) : null}
          </div>

          {/* Photo column */}
          {photo ? (
            <div className="md:w-5/12 md:shrink-0">
              {animate ? (
                <m.figure
                  initial={{ opacity: 0, scale: 0.97 }}
                  whileInView={{ opacity: 1, scale: 1 }}
                  viewport={{ once: true, amount: 0.3 }}
                  transition={{ duration: 0.6, ease: 'easeOut' }}
                  className="overflow-hidden rounded-lg"
                >
                  <img
                    src={photo}
                    alt={photoAlt ?? ''}
                    className="block h-auto w-full object-cover"
                    loading="lazy"
                  />
                </m.figure>
              ) : (
                <figure className="overflow-hidden rounded-lg">
                  <img
                    src={photo}
                    alt={photoAlt ?? ''}
                    className="block h-auto w-full object-cover"
                    loading="lazy"
                  />
                </figure>
              )}
            </div>
          ) : null}
        </div>
      </section>
    </LazyMotion>
  );
}

